/*
 * A326752  BII-numbers of hypertrees.
 * https://oeis.org/A326752
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth smallest integer n whose set‑system derived from
 *            the BII-number n is a hypertree. The sequence is generated by
 *            testing each integer in increasing order for the hypertree
 *            property
 * Range:     u8 n <= 12, u16 n <= 51, u32 n <= 51, u64 n <= 51, u128 n <= 51,
 *            big any n
 * Helpers:   dsu_find, dsu_union, isHypertree
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/dsu_find.h"
#include "../utils/dsu_union.h"
#include "../utils/isHypertree.h"

/* The main sequence function. */
seq_t a(idx_t n)
{
    static seq_t *seq = NULL;
    static size_t seq_len = 0;
    static size_t seq_cap = 0;
    static uint64_t next_candidate = 1;   /* next number to test */

    if (seq_len == 0) {          /* initialise with the first term 0 */
        seq_cap = 1;
        seq = (seq_t *)malloc(seq_cap * sizeof(seq_t));
        seq[0] = (seq_t)0;
        seq_len = 1;
        next_candidate = 1;
    }

    while (seq_len < n) {
        uint64_t cand = next_candidate;
        while (!isHypertree(cand)) ++cand;

        if (seq_len == seq_cap) {
            seq_cap = seq_cap ? seq_cap * 2 : 4;
            seq = (seq_t *)realloc(seq, seq_cap * sizeof(seq_t));
        }
        seq[seq_len++] = (seq_t)cand;
        next_candidate = cand + 1;
    }
    return seq[n - 1];
}
